#pragma bank 255
#include "frontend_resolve.h"
#include "sidebar_items.h"
uint8_t frontend_resolve_icon(uint8_t family,uint8_t id,SidebarJokerRef *o) BANKED {uint8_t n=id;if(!family){if(id>=150)return 0;if(id<75){o->bank=BANK(sidebar_joker_tiles_0);o->tiles=sidebar_joker_tiles_0;o->palette=sidebar_joker_palettes_0;}else{n-=75;o->bank=BANK(sidebar_joker_tiles_1);o->tiles=sidebar_joker_tiles_1;o->palette=sidebar_joker_palettes_1;}}else switch(family){case 1:if(id>=12)return 0;o->bank=BANK(sidebar_planet_tiles);o->tiles=sidebar_planet_tiles;o->palette=sidebar_planet_palettes;break;case 2:if(id>=22)return 0;o->bank=BANK(sidebar_tarot_tiles);o->tiles=sidebar_tarot_tiles;o->palette=sidebar_tarot_palettes;break;case 3:if(id>=18)return 0;o->bank=BANK(sidebar_spectral_tiles);o->tiles=sidebar_spectral_tiles;o->palette=sidebar_spectral_palettes;break;case 4:if(id>=32)return 0;if(id>=8&&id<16){n=id-8;o->bank=BANK(sidebar_celestial_tiles);o->tiles=sidebar_celestial_tiles;o->palette=sidebar_celestial_palettes;}else{n=id<8?id:id-8;o->bank=BANK(sidebar_booster_other_tiles);o->tiles=sidebar_booster_other_tiles;o->palette=sidebar_booster_other_palettes;}break;case 5:if(id>=8)return 0;o->bank=BANK(sidebar_enhancement_tiles);o->tiles=sidebar_enhancement_tiles;o->palette=sidebar_enhancement_palettes;break;default:return 0;}o->tiles+=(uint16_t)n*96;o->palette+=(uint16_t)n*4;return 1;}
